  specialCases: [
    {
      id: 'say-vs-tell',
      title: 'Say va Tell farqi (batafsil)',
      rule: "Say + (that) + clause (person KERAK EMAS):\n  He said (that) he was tired.\n  She said (that) she liked coffee.\n\nTell + person + (that) + clause (person KERAK):\n  He told me (that) he was tired.\n  She told him (that) she liked coffee.\n\nSay + to + person (rasmiy):\n  He said to me (that) he was tired.\n\nTell + object WITHOUT 'to':\n  ❌ He told to me (NOTO'G'RI)\n  ✅ He told me (TO'G'RI)",
      mnemonic: "Say = + that (kimgadir AYTILMASLIGI MUMKIN). Tell = + person + that (KIMGADIR AYTILISHI KERAK). Tell 'to' MAS, 'to' faqat say bilan.",
      commonMistakes: "❌ He told that he was tired (He told me / He said)\n❌ He said me that (He told me / He said)\n❌ She told to me (She told me)",
      examples: [
        { en: 'He said that he was tired.', uz: 'U charchaganini aytdi.' },
        { en: 'He told me that he was tired.', uz: 'U menga charchaganini aytdi.' },
        { en: 'She said hello to me.', uz: 'U menga salom aytdi.' },
      ],
      drills: [
        { id: 19141, type: 'fill-blank', instruction: "Say yoki tell:", question: 'He ___ he was tired.', blanks: ['said'], explanation: "Say + that (person kerak emas)" },
        { id: 19142, type: 'fill-blank', instruction: "Say yoki tell:", question: 'She ___ me (that) she was happy.', blanks: ['told'], explanation: "Tell + person (me) + that" },
        { id: 19143, type: 'error-correction', instruction: "Xatoni toping va to'g'rilang:", question: 'He told that he was tired.', errorPart: 'told', correct: 'He said that he was tired.', explanation: "Tell + person kerak: told me" },
      ],
    },
    {
      id: 'tense-backshift',
      title: 'Tense Backshift batafsil',
      rule: "Direct → Reported (zaman orqaga siljiydi):\n\n'like' → liked (Present → Past)\n'is reading' → was reading (Present Cont → Past Cont)\n'have seen' → had seen (Present Perf → Past Perf)\n'saw' → had seen (Past → Past Perfect)\n'will go' → would go (Will → Would)\n'can swim' → could swim (Can → Could)\n'may come' → might come (May → Might)\n'must go' → had to go (Must → Had to)\n\n🔴 ISTISNO: Agar hali ham to'g'ri bo'lsa, zamanni o'zgartirmaslik mumkin:\n  'The earth is round.' → He said the earth is round. (haqiqat)",
      mnemonic: "Present → Past, Past → Past Perfect, Will → Would, Can → Could. ORQAGA bir zamon.",
      commonMistakes: "❌ He said he likes coffee (like → liked)\n❌ She said she will come (will → would)\n❌ He said he can swim (can → could)",
      examples: [
        { en: "'I like coffee.' → He said he liked coffee.", uz: 'U kofe yoqtirishini aytdi.' },
        { en: "'I will help you.' → She said she would help me.", uz: 'U yordam berishini aytdi.' },
      ],
      drills: [
        { id: 19144, type: 'fill-blank', instruction: "To'g'ri backshift qiling:", question: "'I like tea.' → He said he ___ tea.", blanks: ['liked'], explanation: "Present → Past: like → liked" },
        { id: 19145, type: 'fill-blank', instruction: "To'g'ri backshift qiling:", question: "'I will come.' → She said she ___ come.", blanks: ['would'], explanation: "Will → Would" },
        { id: 19146, type: 'multiple-choice', instruction: "To'g'ri variantni tanlang:", question: "'I can swim.' → He said he ___ swim.", options: ['can', 'could', 'caned', 'coulded'], correct: 'could', explanation: "Can → Could — o'tmishda imkonlik: could do" },
      ],
    },
    {
      id: 'reported-questions',
      title: 'Reported questions — savol so\'z tartibi',
      rule: "Wh- questions:\n  Direct: 'Where do you live?'\n  Reported: He asked where I lived.\n  (So'z tartibi: subject + verb, do/does YO'Q!)\n\nYes/No questions:\n  Direct: 'Do you like coffee?'\n  Reported: He asked if/whether I liked coffee.\n\n🔴 QOIDA: Reported question da so'z tartibi DOIM subject + verb!\n  ❌ He asked where did I live.\n  ✅ He asked where I lived.\n  ❌ She asked if did I like tea.\n  ✅ She asked if I liked tea.",
      mnemonic: "Reported question = subject + verb (do/does/did KERAK EMAS!). If/whether = yes/no savollari uchun.",
      commonMistakes: "❌ He asked where do I live (where I lived)\n❌ She asked if I am ready (if I was ready)\n❌ They asked what did I want (what I wanted)",
      examples: [
        { en: '"Where do you live?" → He asked where I lived.', uz: 'U qayerda yashashimni so\'radi.' },
        { en: '"Do you like tea?" → She asked if I liked tea.', uz: 'U choy yoqtirishimni so\'radi.' },
      ],
      drills: [
        { id: 19147, type: 'fill-blank', instruction: "Reported question:", question: '"Where do you live?" → He asked where I ___.', blanks: ['lived'], explanation: "So'z tartibi: subject + lived" },
        { id: 19148, type: 'fill-blank', instruction: "Reported yes/no:", question: '"Do you like coffee?" → She asked ___ I liked coffee.', blanks: ['if'], explanation: "Yes/no → if/whether" },
        { id: 19149, type: 'error-correction', instruction: "Xatoni toping va to'g'rilang:", question: 'He asked where did I live.', errorPart: 'did I live', correct: 'He asked where I lived.', explanation: "Reported question: subject + verb" },
      ],
    },
  ],
